class Solution {
public:
    int scheduleCourse(vector<vector<int>>& courses) {
        sort(courses.begin(), courses.end(), [](const auto& a, const auto& b) {
            return a[1] < b[1];
        });
        priority_queue<int> pq;
        int totalTime = 0;

        for (const auto& c : courses) {
            int dur = c[0], last = c[1];
            pq.push(dur);
            totalTime += dur;
            if (totalTime > last) {
                totalTime -= pq.top();
                pq.pop();
            }
        }
        return pq.size();
    }
};

class Solution {
    public int scheduleCourse(int[][] courses) {
        Arrays.sort(courses, (a, b) -> Integer.compare(a[1], b[1]));
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        int totalTime = 0;

        for (int[] c : courses) {
            int dur = c[0], last = c[1];
            pq.offer(dur);
            totalTime += dur;
            if (totalTime > last) {
                totalTime -= pq.poll();
            }
        }
        return pq.size();
    }
}

var scheduleCourse = function(courses) {
    courses.sort((a, b) => a[1] - b[1]);
    const heap = [];

    function pushHeap(val) {
        heap.push(val);
        let i = heap.length - 1;
        while (i > 0) {
            let p = (i - 1) >> 1;
            if (heap[p] >= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    }

    function popHeap() {
        const top = heap[0];
        const bottom = heap.pop();
        if (heap.length > 0) {
            heap[0] = bottom;
            let i = 0;
            while ((i << 1) + 1 < heap.length) {
                let left = (i << 1) + 1;
                let right = left + 1;
                let best = (right < heap.length && heap[right] > heap[left]) ? right : left;
                if (heap[i] >= heap[best]) break;
                [heap[i], heap[best]] = [heap[best], heap[i]];
                i = best;
            }
        }
        return top;
    }

    let totalTime = 0;
    for (const [dur, last] of courses) {
        pushHeap(dur);
        totalTime += dur;
        if (totalTime > last) {
            totalTime -= popHeap();
        }
    }
    return heap.length;
};
